# Reproducible source-only build snapshot for the continuity diagnostic.
# No certificates, credentials, device identifiers, or binaries are embedded.
from pathlib import Path
import base64,hashlib,io,os,subprocess,sys,zipfile
_SNAPSHOT = ""
_DIGEST = "c9805f59cce7c9d1e4da5cd473cec8b2c40b4952a88d3dc453750801ac07baf6"
_data=base64.b64decode(_SNAPSHOT)
if hashlib.sha256(_data).hexdigest()!=_DIGEST:raise RuntimeError("Source snapshot checksum mismatch")
_root=Path(__file__).resolve().parent
with zipfile.ZipFile(io.BytesIO(_data)) as _z:
 if __name__!='__main__':
  exec(compile(_z.read('build.py'),str(_root/'build.py'),'exec'),globals())
 else:
  for _info in _z.infolist():
   _path=(_root/_info.filename).resolve()
   if not _path.is_relative_to(_root) or _info.is_dir() or _info.file_size>1000000:raise RuntimeError("Invalid source snapshot")
   _path.parent.mkdir(parents=True,exist_ok=True);_path.write_bytes(_z.read(_info))
if __name__=='__main__':
 _env=os.environ.copy();_env['PYTHONUTF8']='1';_env['PYTHONDONTWRITEBYTECODE']='1'
 subprocess.run([sys.executable,'-B','-m','unittest','discover','-s',str(_root/'tests'),'-v'],env=_env,check=True)
 subprocess.run([sys.executable,'-B',str(_root/'build.py')],env=_env,check=True)
